function fail(m) { throw Error(m); }
function abs(u, base) { u=String(u||'').trim();if(/^[A-Za-z][A-Za-z0-9+.-]*:/.test(u)&&!/^https?:/i.test(u)||u.charAt(0)==='#')return '';return xx.resolve(base || env.baseUrl + '/', u); }
