function request(u, method, body, headers, cookies) {
 var options={url:abs(u).split('#')[0],method:method||'GET',headers:headers||{}};if(P.legacy&&!options.headers['User-Agent'])options.headers['User-Agent']=P.adapter==='xinmanhua'?'okhttp/3.10.0':P.adapter==='dingmanhua'?'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:10.0) Gecko/20100101 Firefox/10.0':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';if(!options.headers.Referer&&P.config&&P.config.referer)options.headers.Referer=P.config.referer;
 if(P.adapter==='copy4000'&&!options.headers.Accept)options.headers.Accept='application/json, text/html;q=0.9, */*;q=0.8';if(P.id==='mangabz')options.headers['User-Agent']=/^\/\d+bz\/$/.test(path(options.url))?'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36':'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 Chrome/120.0 Mobile Safari/537.36';if(body!=null)options.body=body;if(cookies){options.cookies=cookies;if(P.adapter==='manwa')options.persistCookies=false;}if(P.charset)options.charset=P.charset;if(P.browser&&options.method==='GET'&&sameSite(options.url,env.baseUrl))options.browser=true;
