function tpl(t,page,word) { var p=Math.max(1,Number(page)||1);return String(t).replace(/\{keyword\}/g,enc(word||'')).replace(/\{page\}/g,p).replace(/\{offset\}/g,(p-1)*12).replace(/\{lelePage\}/g,p===1?'':'_'+(p-1)).replace(/\{empirePage\}/g,p===1?'':'/index_'+p+'.html').replace(/\{mangaPage\}/g,p===1?'':'/page'+(p-1)+'.html'); }
function literal(s) {
 s=String(s).trim();var quote=s.charAt(0),out='';if(quote!=="'"&&quote!=='"')fail('数据字符串格式无效');
 for(var i=1;i<s.length;i++){var c=s.charAt(i);if(c===quote)return out;if(c!=='\\'){out+=c;continue;}c=s.charAt(++i);
  if(c==='x'||c==='u'){var size=c==='x'?2:4,hex=s.substr(i+1,size);if(!new RegExp('^[a-fA-F0-9]{'+size+'}$').test(hex))fail('字符串转义无效');out+=String.fromCharCode(parseInt(hex,16));i+=size;}
  else if(c==='n')out+='\n';else if(c==='r')out+='\r';else if(c==='t')out+='\t';else if(c==='b')out+='\b';else if(c==='f')out+='\f';else if(c!=='\n'&&c!=='\r')out+=c;
 }fail('数据字符串不完整');
}
function quotedEnd(s, start) { var quote=s.charAt(start),escaped=false;for(var n=start+1;n<s.length;n++){var c=s.charAt(n);if(escaped)escaped=false;else if(c==='\\')escaped=true;else if(c===quote)return n+1;}fail('数据字符串不完整'); }
function balanced(s,start) { var open=s.charAt(start),close=open==='['?']':'}',depth=0;for(var n=start;n<s.length;n++){var c=s.charAt(n);if(c==='"'||c==="'"){n=quotedEnd(s,n)-1;continue;}if(c===open)depth++;else if(c===close&&--depth===0)return s.substring(start,n+1);}fail('数据结构不完整'); }
function dataLiteral(s) {
 var at=0,count=0;function skip(){while(/\s/.test(s.charAt(at))&&at<s.length)at++;}
 function read(depth){if(depth>64||++count>100000)fail('页面数据嵌套或数量过多');skip();var c=s.charAt(at),start=at,result;
  if(c==='"'||c==="'"){at=quotedEnd(s,at);return literal(s.substring(start,at));}
  if(c==='['||c==='{'){at++;result=c==='['?[]:{};skip();while(s.charAt(at)!==(c==='['?']':'}')){if(at>=s.length)fail('数据结构不完整');var key;if(c==='{'){skip();var k=s.charAt(at);if(k==='"'||k==="'"){var end=quotedEnd(s,at);key=literal(s.substring(at,end));at=end;}else{key=match(s.substring(at),/^([A-Za-z_$][\w$]*)/);if(!key)fail('数据字段无效');at+=key.length;}if(key==='__proto__'||key==='constructor'||key==='prototype')fail('不允许的字段');skip();if(s.charAt(at++)!==':')fail('数据字段缺少冒号');result[key]=read(depth+1);}else result.push(read(depth+1));skip();if(s.charAt(at)===','){at++;skip();}else if(s.charAt(at)!==(c==='['?']':'}'))fail('数据分隔无效');}at++;return result;}
  var token=match(s.substring(at),/^(-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null)(?![\w$])/);if(!token)fail('页面数据包含不可执行的表达式');at+=token.length;return JSON.parse(token);
