function earlId(value) {
    var id = String(value);
    if (!/^[1-9]\d*$/.test(id)) fail('作品编号无效');
    return id;
}

function earlDirectory(bookId, chapterId) {
    var referer = abs('/cartoon/' + bookId + (chapterId ? '/' + chapterId : ''));
    var params = {cartoonid: bookId};
    if (chapterId) {
        params.chapterid = chapterId;
        params.picidx = 1;
        params.pageSize = 4;
        params.tuid = 0;
    }
    var response = json(post('/ApiChapter/CartoonChapterList', form(params), referer, {
        Origin: env.baseUrl,
        'X-Requested-With': 'XMLHttpRequest',
        Accept: 'application/json'
    }));
    if (typeof response === 'string') response = json(response);
    if (!response || response.state !== true || !Array.isArray(response.data)) fail('没有取得公开章节目录');
    return response;
}

function earlFreeRows(data, bookId) {
    var ids = Object.create(null);
    for (var i = 0; i < data.length; i++) {
        var row = data[i];
        var id = row && String(row.id);
        if (!row || !/^[1-9]\d*$/.test(id) || ids[id] || row.isvip == null || Number(row.isvip) !== 0
                || row.isUnlocked !== true || !Number.isInteger(row.piccount) || row.piccount < 1
                || !own(row.url) || path(row.url) !== '/cartoon/' + bookId + '/' + id) return [];
        ids[id] = true;
    }
    return data;
}

function earlRemember(bookId, free) {
    xx.cacheSet('earl:free:' + bookId, JSON.stringify({free: free, expires: Date.now() + 120000}));
    return free;
}

function earlCanRead(bookId) {
    var saved = xx.cacheGet('earl:free:' + bookId);
    if (saved) {
        var state = json(saved);
        if (state.expires > Date.now()) return state.free;
    }
    return earlRemember(bookId, earlFreeRows(earlDirectory(bookId).data, bookId).length > 0);
}

function earlImage(node, base) {
    var url = abs(image(node), base);
    if (!/^https:\/\/store\.earl123\.com\/cartoon\//i.test(url)) fail('图片地址无效');
    return url;
}

function earlList(filters, page, keyword) {
    var genre = val(filters, 'genre');
    var status = val(filters, 'status');
    if (genre && !/^\d+$/.test(genre)) fail('题材筛选无效');
    var url = keyword ? '/Cartoon/Search?query=' + enc(keyword) : '/category/cartoon' + (genre ? '/' + genre : '') + '?vip=free';
    if (!keyword && /^(serial|finished)$/.test(status)) url += '&finish=' + status;
    if (!keyword && val(filters, 'sort') === 'new') url += '&sort=new';
    var selector = keyword ? '.mainlist .cartoon_box a[href]' : '.cartoon-category-page .mainlist .io[onclick]';
    var pageNumber = Math.max(1, Math.floor(Number(page) || 1));
    // A native search page contains up to 30 cards. Check ten directories per app page.
    var searchOffset = ((pageNumber - 1) % 3) * 10;
    var nativePage = keyword ? Math.floor((pageNumber - 1) / 3) + 1 : pageNumber;
    var previous = [];
    if (keyword && nativePage > 1) {
        var priorPage = get(url + '&pi=' + (nativePage - 1));
        if (!own(priorPage.url)) fail('搜索发生跳转');
        previous = q(priorPage.body, selector, priorPage.url);
        if (previous.length < 30) return {items: [], hasMore: false};
    }
    var response = get(url + '&pi=' + nativePage);
    if (!own(response.url)) fail('站源列表发生跳转');
    var cards = q(response.body, selector, response.url);
    if (previous.length === cards.length && cards.length && cards.every(function(card, index) {
        return card.href === previous[index].href;
    })) return {items: [], hasMore: false};
    var books = [];
    var visible = keyword ? cards.slice(searchOffset, searchOffset + 10) : cards;
    visible.forEach(function(card) {
        var bookUrl = keyword ? card.href : match(card.attrs.onclick, /^location\.href\s*=\s*['"]([^'"]+)['"];?$/);
        var bookId = own(bookUrl) && match(path(bookUrl), /^\/cartoon\/([1-9]\d*)$/);
        if (!bookId) return;
        if (keyword) {
            // Search results mix free and paid works. The directory supplies the access state.
            if (!/^\s*[1-9]\d*\s*章\s*$/.test(text(card.html, '.cartoon_left_bottom_right')) || !earlCanRead(bookId)) return;
        } else {
            // The free list includes scheduled releases that may have no chapters yet.
            var views = Number(text(card.html, 'span.shrink-0').replace(/,/g, ''));
            if (!(views > 0) && !earlCanRead(bookId)) return;
        }
        var title = text(card.html, keyword ? '.cartoon_box_title' : 'h4');
        var author = text(card.html, keyword ? '.carton_box_course' : 'span.truncate');
        books.push(summary(bookId, title, earlImage(one(card.html, 'img[src]', response.url), response.url), author));
    });
    if (!keyword && !one(response.body, '.cartoon-category-page .mainlist')) fail('没有取得免费漫画列表');
    return {
        items: unique(books, function(book) { return book.id; }),
        hasMore: keyword ? cards.length > searchOffset + 10 || cards.length === 30
            : !!attr(response.body, '.cartoon-category-page [data-next]', 'data-next')
    };
}

function earlFilters() {
    var response = get('/category/cartoon?vip=free');
    var choices = ['全部', 'all'];
    q(response.body, '.cartoon-category-page button[onclick]').forEach(function(button) {
        var id = match(button.attrs.onclick, /\/category\/cartoon\/(\d+)\?vip=free['"]/);
        if (id && choices.indexOf(id) < 0) choices.push(button.text.trim(), id);
    });
    if (choices.length < 4) fail('没有取得漫画题材');
    return [group('genre', '题材', choices), group('status', '进度', ['全部', 'all', '连载中', 'serial', '已完结', 'finished']),
        group('sort', '排序', ['最热', 'all', '最新', 'new'])];
}

function earlDetail(key) {
    var id = earlId(key);
    var url = '/cartoon/' + id;
    var response = get(url);
    if (!own(response.url) || path(response.url) !== url) fail('详情作品身份不匹配');
    var title = text(response.body, '.cartoon_middle_box .cartoon_title');
    var cover = earlImage(one(response.body, '.cartoon-cover-badge-wrap img[src]', response.url), response.url);
    var author = text(response.body, '.cartoon_middle_box .cartoon_course').replace(/^作者\s*[:：]\s*/, '');
    var book = summary(id, title, cover, author);
    book.author = author;
    book.status = text(response.body, '.cartoon-cover-badge-wrap .cartoon_left_bottom_left');
    book.description = text(response.body, '.cartoon_middle_box .cartoon_desc');
    return book;
}

function earlChapters(key) {
    var id = earlId(key);
    var rows = earlFreeRows(earlDirectory(id).data, id);
    earlRemember(id, rows.length > 0);
    if (!rows.length) fail('没有取得完整免费目录');
    return slots(rows.map(function(row) {
        return chapter(row.id, String(row.name || ('第' + row.idx + '章')), row.url);
    }));
}

function earlRead(url) {
    var matchUrl = own(url) && path(url).match(/^\/cartoon\/([1-9]\d*)\/([1-9]\d*)$/);
    if (!matchUrl) fail('章节地址无效');
    var bookId = matchUrl[1];
    var chapterId = matchUrl[2];
    var route = matchUrl[0];
    var directory = earlDirectory(bookId, chapterId);
    var entry = earlFreeRows(directory.data, bookId).filter(function(row) { return String(row.id) === chapterId; })[0];
    if (!entry) fail('没有取得完整免费正文');
    var count = entry.piccount;
    if (count > 1000) fail('章节页数超过规则请求上限');
    if (count > 4 && (!directory.nextNav || directory.nextNav.itemType !== 'pic' || directory.nextNav.url !== route + '/5')) {
        fail('阅读分页地址不匹配');
    }
    var images = [];
    // The site's reader exposes four consecutive images at each numbered route.
    for (var start = 1; start <= count; start += 4) {
        var screen = route + (start === 1 ? '' : '/' + start);
        var response = get(screen, abs(route));
        var identity = one(response.body, '#cartoon_reading_comments');
        if (!own(response.url) || path(response.url) !== screen || !identity
                || identity.attrs['data-cartoon-id'] !== bookId || identity.attrs['data-chapter-id'] !== chapterId) {
            fail('正文作品或章节身份不匹配');
        }
        var batch = q(response.body, '.cartoon_detail_image img.cartoon_detail_img[src]', response.url);
        if (batch.length !== Math.min(4, count - start + 1)) fail('正文缺页');
        batch.forEach(function(node) { images.push(earlImage(node, response.url)); });
    }
    if (unique(images).length !== count) fail('正文分页重复');
    return pageImages(abs(route), images, String(entry.name || ''));
}

var source = {
    filters: earlFilters,
    latest: function(page) { return earlList({}, page, ''); },
    category: function(filters, page) { return earlList(filters, page, ''); },
    search: function(keyword, page) {
        var query = String(keyword || '').trim();
        return query ? earlList({}, page, query) : {items: [], hasMore: false};
    },
    detail: earlDetail,
    chapters: earlChapters,
    chapter: earlRead
};

