function wwzuId(value) {
    var id = String(value || '');
    if (!/^\d+$/.test(id)) fail('作品编号无效');
    return id;
}

function wwzuData(url, referer) {
    var response = get(url, referer);
    if (!own(response.url)) fail('站源接口发生跳转');
    var result = json(response);
    if (!result || result.success !== true || !result.data) fail('没有取得连环画数据');
    return result.data;
}

function wwzuPicture(value) {
    return /^https:\/\/photourl\.wwzu\.com\/web_thumbs\//i.test(value || '') ? value : '';
}

function wwzuSummary(row) {
    var book = summary(wwzuId(row.htmlname), row.title, wwzuPicture(row.cover), String(row.author || row.publisher || ''));
    book.tags = unique(String(row.tab || '').split(/[,，]/).map(function(tag) {
        return tag.trim();
    }).filter(function(tag) {
        return tag && tag.length <= 80;
    }));
    return book;
}

function wwzuListRows(rows) {
    if (!Array.isArray(rows)) fail('没有取得连环画列表');
    return unique(rows.filter(function(row) {
        return row && /^\d+$/.test(row.htmlname) && String(row.title || '').trim()
            && Number(row.page_count) > 0 && wwzuPicture(row.cover);
    }).map(wwzuSummary), function(book) { return book.id; });
}

function wwzuList(filters, page) {
    var sort = val(filters, 'sort', 'hits');
    if (!/^(hits|rating|wwwid)$/.test(sort)) fail('排序无效');
    var tag = val(filters, 'tag');
    var data = wwzuData('/api/comics/list?' + form({
        page: page, per_page: 24, sort: sort, order: 'desc', tag: tag
    }));
    var pagination = data.pagination;
    if (!pagination || Number(pagination.page) !== page || !Number.isFinite(Number(pagination.total_pages))) {
        fail('连环画列表分页无效');
    }
    return {items: wwzuListRows(data.comics), hasMore: page < Number(pagination.total_pages)};
}

function wwzuFilters() {
    var response = get('/categories.php');
    if (!own(response.url)) fail('标签页发生跳转');
    var tags = variable(response.body, '__TAGS_DATA');
    if (!Array.isArray(tags) || !tags.length) fail('没有取得公开题材列表');
    var choices = ['全部', 'all'];
    tags.forEach(function(row) {
        if (row && typeof row.name === 'string' && row.name.trim() && Number(row.count) > 0) {
            choices.push(row.name, row.name);
        }
    });
    return [
        group('tag', '题材', choices),
        group('sort', '排序', ['阅读最多', 'hits', '评分最高', 'rating', '最新上架', 'wwwid'])
    ];
}

function wwzuBookUrl(id) {
    return '/comic-detail/' + id;
}

function wwzuBook(id) {
    var data = wwzuData('/api/comics/detail?htmlname=' + id, abs(wwzuBookUrl(id)));
    if (!data.comic || String(data.comic.htmlname) !== id || !Array.isArray(data.pages)
            || !data.pages.length || data.pages.length !== Number(data.comic.page_count)) {
        fail('没有取得该作品的完整公开正文');
    }
    return data;
}

function wwzuDetail(key) {
    var row = wwzuBook(wwzuId(key)).comic;
    var book = wwzuSummary(row);
    book.author = String(row.author || '');
    var notes = String(row.copyright || '');
    if (notes && notes.indexOf('[object Object]') < 0) book.description = notes;
    return book;
}

function wwzuRead(url) {
    var id = own(url) && match(path(url), /^\/comic-detail\/(\d+)$/);
    if (!id) fail('阅读地址无效');
    var data = wwzuBook(id);
    var images = data.pages.map(function(row, index) {
        var imageUrl = row && wwzuPicture(row.image_url);
        if (!imageUrl || Number(row.page_number) !== index + 1) fail('连环画页表缺页');
        return imageUrl;
    });
    if (unique(images).length !== images.length) fail('连环画页表有重复图片');
    return pageImages(abs(wwzuBookUrl(id)), images, data.comic.title);
}

var source = {
    filters: wwzuFilters,
    latest: function(page) { return wwzuList({}, page); },
    category: wwzuList,
    search: function(keyword, page) {
        // The site provides one batch of suggestions for a title query.
        var query = String(keyword || '').trim();
        if (!query || page > 1) return {items: [], hasMore: false};
        return {items: wwzuListRows(wwzuData('/api/search?q=' + enc(query)).comics), hasMore: false};
    },
    detail: wwzuDetail,
    chapters: function(key) {
        var id = wwzuId(key);
        return slots([chapter(id, '全册', wwzuBookUrl(id))]);
    },
    chapter: wwzuRead
};

