function zhlContext() {
    var saved = xx.cacheGet('zhl:catalog');
    if (saved) {
        var cached = json(saved);
        if (cached.expires > Date.now()) return cached;
    }
    var response = get('/zhlhhlib');
    if (!own(response.url)) fail('数字阅读馆入口发生跳转');
    var searchLink = one(response.body, 'a[href*="/Search/Index?"]', response.url);
    var library = searchLink && match(searchLink.href, /[?&]libcode=([A-Fa-f0-9]{32,256})(?:&|$)/);
    if (!library) fail('没有取得公开阅读馆编号');
    var topics = {};
    q(response.body, 'a[href*="/Home/IsZJShowList?"]', response.url).forEach(function(link) {
        var key = match(link.href, /[?&]b=([A-Za-z0-9]+)(?:&|$)/);
        var id = match(link.href, /[?&]a=([A-Za-z0-9-]+)(?:&|$)/);
        if (id && Object.prototype.hasOwnProperty.call(P.config.topics, key)) topics[key] = id;
    });
    if (!topics[P.config.defaultTopic]) fail('没有取得公开连环画分类');
    var result = {library: library, topics: topics, expires: Date.now() + 300000};
    xx.cacheSet('zhl:catalog', JSON.stringify(result));
    return result;
}

function zhlId(value) {
    var id = String(value || '').toUpperCase();
    if (!/^[A-F0-9]{32,96}$/.test(id)) fail('作品编号无效');
    return id;
}

function zhlPicture(value) {
    var url = abs(value);
    return own(url) && /^\/source\/zhlhh\/(?:pic|src)\//i.test(path(url)) ? url : '';
}

function zhlResults(route, params, referer, page) {
    var response = post(route, form(params), referer, {
        Origin: env.baseUrl, 'X-Requested-With': 'XMLHttpRequest'
    });
    if (!own(response.url)) fail('阅读馆列表发生跳转');
    var data = json(response);
    if (!data || data.isSuccess !== true || !Array.isArray(data.result)
            || !Number.isFinite(Number(data.resultOther))) fail('没有取得阅读馆列表');
    var books = data.result.filter(function(row) {
        return row && /^[A-Fa-f0-9]{32,96}$/.test(row.BHJM)
            && String(row.MC || '').trim() && zhlPicture(row.SLT);
    }).map(function(row) {
        var book = summary(zhlId(row.BHJM), row.MC, zhlPicture(row.SLT), String(row.YZ || row.HH || ''));
        if (row.FLMC) book.tags = [String(row.FLMC)];
        return book;
    });
    return {items: unique(books, function(book) { return book.id; }), hasMore: page < Number(data.resultOther)};
}

function zhlList(filters, page) {
    var context = zhlContext();
    var topic = val(filters, 'topic', P.config.defaultTopic);
    var id = Object.prototype.hasOwnProperty.call(context.topics, topic) && context.topics[topic];
    if (!id) fail('该连环画分类不可用');
    var referer = '/Home/IsZJShowList?' + form({libcode: context.library, a: id, b: topic});
    return zhlResults('/Home/AjaxShowList', {
        page: page, size: 16, showclassid: id, libcode: context.library
    }, abs(referer), page);
}

function zhlReaderUrl(id) {
    return abs('/Reader/Index?' + form({libcode: zhlContext().library, bh: id}));
}

function zhlRead(id) {
    var url = zhlReaderUrl(id);
    var response = get(url, P.config.referer);
    var actual = match(response.url, /[?&]bh=([A-Fa-f0-9]{32,96})(?:&|$)/);
    if (!own(response.url) || path(response.url) !== '/Reader/Index' || actual.toUpperCase() !== id) {
        fail('阅读馆作品地址不匹配');
    }
    var title = text(response.body, 'title', response.url);
    var pages = variable(response.body, 'items');
    if (!title || !Array.isArray(pages) || !pages.length) fail('没有取得公开连环画正文');
    var images = pages.map(function(row) {
        var imageUrl = row && zhlPicture(row.src);
        if (!imageUrl) fail('连环画页表缺页');
        return imageUrl;
    });
    if (unique(images).length !== images.length) fail('连环画页表有重复图片');
    return pageImages(url, images, title);
}

var source = {
    filters: function() {
        var topics = zhlContext().topics;
        var choices = [];
        Object.keys(P.config.topics).forEach(function(key) {
            if (topics[key]) choices.push(P.config.topics[key], key);
        });
        return [group('topic', '分类', choices)];
    },
    latest: function(page) { return zhlList({}, page); },
    category: zhlList,
    search: function(keyword, page) {
        var query = String(keyword || '').trim();
        if (!query) return {items: [], hasMore: false};
        var library = zhlContext().library;
        return zhlResults('/Search/PostSearchName', {
            page: page, size: 16, name: query, lib: library
        }, abs('/Search/Index?libcode=' + enc(library)), page);
    },
    detail: function(key) {
        var id = zhlId(key);
        var book = zhlRead(id);
        return summary(id, book.title, book.images[0].url, '');
    },
    chapters: function(key) {
        var id = zhlId(key);
        return slots([chapter(id, '全册', zhlReaderUrl(id))]);
    },
    chapter: function(url) {
        if (!own(url) || path(url) !== '/Reader/Index') fail('阅读地址无效');
        return zhlRead(zhlId(match(url, /[?&]bh=([A-Fa-f0-9]{32,96})(?:&|$)/)));
    }
};

