    if (/無法顯示此網頁|无法显示此网页|not available in your (?:country|region)/i.test(response.body) && response.body.length < 12000) {
        fail('当前网络无法打开繁中 CANVAS，请检查 VPN 线路');
    }
    return response;
}

function canvasId(value) {
    if (!/^\d{1,12}$/.test(String(value))) fail('作品或章节编号无效');
    return String(value);
}

function canvasParam(url, key) {
    return match(file(url), new RegExp('[?&]' + key + '=(\\d{1,12})(?:&|$)'));
}

function canvasPhoto(value) {
    if (!value) return '';
    var url = abs(value, 'https://webtoon-phinf.pstatic.net/');
    return /^https:\/\/(?:s?webtoon-phinf\.pstatic\.net)\//i.test(url) ? url : '';
}

function canvasFilters() {
    var response = canvasGet(canvasRoute + '?genreTab=ALL');
    var options = ['全部', 'all'];
    var seen = {ALL: true};
    q(response.body, 'a.snb_tab[href*="genreTab="]', response.url).forEach(function(link) {
        var key = match(link.href, /[?&]genreTab=([A-Z0-9_]+)(?:&|$)/);
        if (own(link.href) && path(link.href) === canvasRoute && key && !seen[key]) {
            seen[key] = true;
            options.push(link.text.trim(), key);
        }
    });
    if (options.length < 4) fail('没有取得原站题材列表');
    return [group('genre', '题材', options),
        group('sort', '排序', [canvasSort.UPDATE, 'all', canvasSort.MANA, 'MANA', canvasSort.LIKEIT, 'LIKEIT'])];
}

function canvasListPage(genre, sort, page) {
    var response = canvasGet(canvasRoute + '?genreTab=' + enc(genre) + '&sortOrder=' + enc(sort) + '&page=' + page);
    if (!own(response.url) || path(response.url) !== canvasRoute || !one(response.body, '.challenge_lst', response.url)) {
        fail('没有取得繁中 CANVAS 作品列表');
    }
    var rows = q(response.body, '.challenge_lst a.challenge_item[href]', response.url);
    var books = [];
    rows.forEach(function(link) {
        var key = canvasParam(link.href, 'title_no');
        if (!key || !own(link.href) || !canvasBook.test(path(link.href))) return;
        var title = text(link.html, '.subj', response.url);
        var cover = canvasPhoto(image(one(link.html, '.img_area img', response.url)));
        if (title && cover) books.push(summary(key, title, cover, text(link.html, '.author', response.url)));
    });
    var more = q(response.body, 'a.pg_page[href],a.pg_next[href]', response.url).some(function(link) {
        return own(link.href) && path(link.href) === canvasRoute && Number(canvasParam(link.href, 'page')) > page;
    });
    return {items: unique(books, function(book) { return book.id; }), hasMore: more};
}

function canvasSearchPage(word, page) {
    var offset = (page - 1) * canvasPageSize;
    var response = canvasGet(P.config.mobile + '/zh-hant/search/result?keyword=' + enc(word)
        + '&searchType=CHALLENGE&start=' + offset);
    var data = json(response);
    var matches = data.result && data.result.challengeResult;
    if (!data.success || !matches || !Array.isArray(matches.titleList)) fail('没有取得 CANVAS 搜索结果');
    var books = [];
    matches.titleList.forEach(function(item) {
        var key = String(item.titleNo || '');
        var cover = canvasPhoto(item.thumbnailMobile || '');
        if (!/^\d{1,12}$/.test(key) || !item.title || !cover || item.unsuitableForChildren) return;
        books.push(summary(key, item.title, cover, item.pictureAuthorName || item.writingAuthorName || ''));
    });
    return {items: unique(books, function(book) { return book.id; }), hasMore: Number(matches.totalCount) > offset + canvasPageSize};
}

function canvasPublicPage(key, page, loadPage) {
    var cursor = 'canvas:' + key + ':';
    var cached = page > 1 && xx.cacheGet(cursor + page);
    var upstream = cached ? Number(cached) : 1;
    var shown = cached ? page : 1;
    for (;; upstream++) {
        var result = loadPage(upstream);
        if (result.items.length) {
            if (result.hasMore) xx.cacheSet(cursor + (shown + 1), String(upstream + 1));
            if (shown === page) return result;
            shown++;
        }
        if (!result.hasMore) return {items: [], hasMore: false};
    }
}

function canvasCategory(filters, page) {
    var genre = val(filters, 'genre', 'ALL');
    var sort = val(filters, 'sort', 'UPDATE');
    if (!/^[A-Z0-9_]{1,32}$/.test(genre) || !Object.prototype.hasOwnProperty.call(canvasSort, sort)) {
        fail('筛选参数无效');
    }
    return canvasPublicPage(genre + ':' + sort, page, function(n) { return canvasListPage(genre, sort, n); });
}

function canvasCheckRating(response) {
    var rating = match(response.body, /regionalContentRatingMap\s*:\s*(\{[^{}]{1,2000}\})/);
    if (!rating) return;
    var regions = json(rating);
    if (Object.keys(regions).some(function(region) { return regions[region] === 'MATURE'; })) {
        fail('作品需先在原站确认年龄');
    }
}

function canvasDetail(id) {
    id = canvasId(id);
    var response = canvasGet('/zh-hant/canvas/a/list?title_no=' + id + '&webtoon-platform-redirect=true');
    if (!own(response.url) || !canvasBook.test(path(response.url)) || canvasParam(response.url, 'title_no') !== id) {
        fail('作品详情不属于繁中 CANVAS');
    }
    canvasCheckRating(response);
    var title = text(response.body, '.info.challenge .subj', response.url);
    var cover = canvasPhoto(attr(response.body, 'meta[property="og:image"]', 'content', response.url));
    if (!title || !cover) fail('没有取得作品标题或封面');
    var book = summary(id, title, cover);
    book.author = text(response.body, '.info.challenge .author_area', response.url);
    book.description = text(response.body, 'p.summary', response.url);
    return book;
}

function canvasChapters(id) {
    id = canvasId(id);
    var cursor = 0;
    var chapters = [];
    do {
        var response = canvasGet(P.config.mobile + '/api/v1/canvas/' + id + '/episodes?pageSize=1000&startIndex=' + cursor);
        var data = json(response);
        var result = data.result;
        if (!data.success || !result || !Array.isArray(result.episodeList)) fail('没有取得访客章节目录');
        result.episodeList.forEach(function(item) {
            var number = String(item.episodeNo || '');
            if (!item.viewerLink) return;
            var url = abs(item.viewerLink);
            if (!own(url) || !canvasReader.test(path(url)) || canvasParam(url, 'title_no') !== id
                    || canvasParam(url, 'episode_no') !== number) fail('章节与作品编号不匹配');
            chapters.push(chapter(number, item.episodeTitle || ('第' + number + '话'), url));
        });
        var next = Number(result.nextCursor) || 0;
        if (next && next <= cursor) fail('章节分页游标异常');
        cursor = next;
    } while (cursor);
    chapters = unique(chapters, function(item) { return item.id; });
    if (!chapters.length) fail('作品暂无访客可读章节');
    chapters.sort(function(a, b) { return Number(a.id) - Number(b.id); });
    return slots(chapters);
}

function canvasRead(url) {
    var id = canvasParam(url, 'title_no');
    var episode = canvasParam(url, 'episode_no');
    if (!own(url) || !canvasReader.test(path(url)) || !id || !episode) fail('阅读地址无效');
    var response = canvasGet(url, url);
    if (!own(response.url) || !canvasReader.test(path(response.url)) || canvasParam(response.url, 'title_no') !== id
            || canvasParam(response.url, 'episode_no') !== episode) fail('阅读页与章节编号不匹配');
    canvasCheckRating(response);
    var images = q(response.body, '#_imageList img[data-url]', response.url).map(function(node) {
        var imageUrl = canvasPhoto(node.attrs['data-url']);
        if (!imageUrl) fail('正文图片域名无效');
        return imageUrl;
    });
    if (!images.length) fail('本话没有提供访客可读图片');
    return pageImages(response.url, images, text(response.body, 'title', response.url));
}

var source = {
    filters: canvasFilters,
    latest: function(page) { return canvasCategory({}, page); },
    category: canvasCategory,
    search: function(keyword, page) {
        var word = String(keyword || '').trim();
        if (!word) return {items: [], hasMore: false};
        return canvasPublicPage('search:' + convert('sha256', word), page, function(n) {
            return canvasSearchPage(word, n);
        });
    },
    detail: canvasDetail,
    chapters: canvasChapters,
    chapter: canvasRead
};

