function qinId(value) {
    var id = String(value);
    if (!/^[1-9]\d*$/.test(id)) fail('作品编号无效');
    return id;
}

function qinCategoryUrl(filters, page) {
    var region = val(filters, 'region', '9');
    var genre = val(filters, 'genre', '全部');
    var status = val(filters, 'status', '3');
    if (!/^[1-49]$/.test(region) || !/^[134]$/.test(status)) fail('分类参数无效');
    var pageNumber = Math.max(1, Math.floor(Number(page) || 1));
    return '/lists/' + region + '/' + enc(genre) + '/' + status + '/' + pageNumber + '.html';
}

function qinList(response, search) {
    if (!own(response.url) || !/^\/(?:lists\/|search\/?$)/.test(path(response.url))) fail('列表地址发生跳转');
    var cards = search ? '.list_center dl' : '.cy_list_mh > ul';
    var books = [];
    q(response.body, cards, response.url).forEach(function(card) {
        var link = one(card.html, search ? 'h3 a[href]' : 'a.pic[href]', response.url);
        var id = link && match(path(link.href), /^\/mh\/(\d+)\/$/);
        if (!id || !own(link.href)) return;
        var imageNode = one(card.html, 'img', response.url);
        var url = image(imageNode);
        var title = link.attrs.title || link.text || imageNode && imageNode.attrs.alt;
        if (title && url) books.push(summary(id, title, abs(url, response.url)));
    });
    return {items: unique(books, function(book) { return book.id; }),
        hasMore: !search && books.length > 0 && !!next(response, '.pages a[href]')};
}

function qinFilters() {
    var response = get(qinCategoryUrl({}, 1));
    var topics = ['全部','all'];
    var states = ['全部','all'];
    var regions = ['全部','all'];
    q(response.body, '#tags a[href]', response.url).forEach(function(a) {
        if (a.text && a.text !== '全部' && topics.indexOf(a.text) < 0) topics.push(a.text, a.text);
    });
    q(response.body, '#jindu a[href]', response.url).forEach(function(a) {
        var state = match(path(a.href), /^\/lists\/\d+\/[^/]+\/([14])\/\d+\.html$/);
        if (state && a.text && states.indexOf(state) < 0) states.push(a.text, state);
    });
    q(response.body, '#diqu a[href]', response.url).forEach(function(a) {
        var region = match(path(a.href), /^\/lists\/([1-4])\/[^/]+\/\d+\/\d+\.html$/);
        if (region && a.text && regions.indexOf(region) < 0) regions.push(a.text, region);
    });
    if (topics.length < 4 || states.length < 4 || regions.length < 4) fail('没有取得原站筛选项');
    return [group('genre','题材',topics), group('status','进度',states), group('region','地区',regions)];
}

function qinDetail(value) {
    var id = qinId(value);
    var url = '/mh/' + id + '/';
    var response = get(url);
    if (!own(response.url) || path(response.url) !== url) fail('详情作品身份不匹配');
    var title = attr(response.body, 'meta[property="og:novel:book_name"]', 'content') || text(response.body, 'h1');
    var cover = attr(response.body, 'meta[property="og:image"]', 'content');
    if (!title || !cover) fail('详情缺少作品或封面');
    var book = summary(id, title, abs(cover, response.url), attr(response.body, 'meta[property="og:novel:author"]', 'content'));
    book.description = attr(response.body, 'meta[property="og:description"]', 'content');
    return book;
}

function qinChapters(value) {
    var id = qinId(value);
    var url = '/menu/' + id + '.html';
    var response = get(url);
    if (!own(response.url) || path(response.url) !== url) fail('目录作品身份不匹配');
    var sections = q(response.body, '.cy_plist', response.url);
    if (!sections.length) fail('没有取得完整章节目录');
    var rows = [];
    var pattern = new RegExp('^/chapter/' + id + '/(\\d+)\\.html$');
    q(sections[sections.length - 1].html, 'a[href]', response.url).forEach(function(link) {
        var cid = match(path(link.href), pattern);
        if (cid && link.text && own(link.href)) rows.push(chapter(cid, link.text, link.href));
    });
    return ordered(rows, sections.length === 1);
}

function qinRead(url) {
    var m = path(url).match(/^(\/chapter\/\d+\/\d+)\.html$/);
    if (!own(url) || !m) fail('章节地址无效');
    var images = [];
    var title = '';
    for (var page = 1; page <= 96; page++) {
        var pagePath = m[1] + (page === 1 ? '' : '_' + page) + '.html';
        var response = get(pagePath, page === 1 ? undefined : url);
        if (!own(response.url) || path(response.url) !== pagePath) fail('正文分页身份不匹配');
        if (!title) title = text(response.body, 'h1') || text(response.body, 'title');
        var batch = q(response.body, '.mh_list img', response.url);
        if (!batch.length) fail('正文分页没有图片');
        batch.forEach(function(node) {
            var value = image(node);
            if (!value) fail('正文分页缺少图片地址');
            images.push({url: abs(value, response.url), referer: response.url});
        });
        var following = q(response.body, 'a[href]', response.url).filter(function(link) {
            return /^(?:下一页|下一頁)$/.test(link.text.trim());
        })[0];
        if (!following) return pageImages(url, images, title);
        if (!own(following.href) || path(following.href) !== m[1] + '_' + (page + 1) + '.html') fail('正文下一页地址异常');
    }
    fail('正文分页超出上限');
}

var source = {
    filters: qinFilters,
    latest: function(page) { return qinList(get(qinCategoryUrl({}, page)), false); },
    category: function(filters, page) { return qinList(get(qinCategoryUrl(filters, page)), false); },
    search: function(keyword, page) {
        var word = String(keyword || '').trim();
        if (!word || Number(page) > 1) return {items: [], hasMore: false};
        return qinList(post('/search/', form({searchkey: word}), abs(qinCategoryUrl({}, 1))), true);
    },
    detail: qinDetail,
    chapters: qinChapters,
    chapter: qinRead
};

