function mh242Id(value) {
    var id = String(value);
    if (!/^[1-9]\d*$/.test(id)) fail('作品编号无效');
    return id;
}

function mh242Page(value) {
    return Math.max(1, Math.floor(Number(value) || 1));
}

function mh242Rows(response) {
    var rows = [];
    q(response.body, 'a.stui-vodlist__thumb[href]', response.url).forEach(function(card) {
        var id = match(path(card.href), /^\/comic\/(\d+)$/);
        var title = card.attrs.title;
        var cover = image(card);
        var latest = text(card.html, '.pic-text');
        if (!id || !own(card.href) || !title || !cover || latest === '待浏览') return;
        var row = summary(id, title, abs(cover, response.url));
        row.latestChapter = latest;
        rows.push(row);
    });
    return unique(rows, function(row) { return row.id; });
}

function mh242Category(filters, page) {
    var tag = val(filters, 'genre');
    var state = val(filters, 'status');
    var order = val(filters, 'sort');
    if (!/^\d*$/.test(tag) || !/^[12]?$/.test(state) || !/^(?:addtime|hits)?$/.test(order)) fail('分类参数无效');
    var url = '/category' + (tag ? '/tags/' + tag : '') + (state ? '/finish/' + state : '') +
        (order ? '/order/' + order : '');
    page = mh242Page(page);
    var response = get(url + (page > 1 ? '/page/' + page : url === '/category' ? '/' : ''));
    if (!own(response.url) || !/^\/category(?:\/|$)/.test(path(response.url))) fail('分类地址发生跳转');
    var rows = mh242Rows(response);
    return {items: rows, hasMore: rows.length > 0 && !!next(response, '.stui-page a[href]')};
}

function mh242Filters() {
    var response = get('/category/');
    var genres = ['全部','all'];
    var states = ['全部','all'];
    var sorting = ['原站默认','all'];
    q(response.body, '.stui-screen__list a[href]', response.url).forEach(function(link) {
        var tag = match(path(link.href), /^\/category\/tags\/(\d+)$/);
        var state = match(path(link.href), /^\/category\/finish\/([12])$/);
        if (tag && genres.indexOf(tag) < 0 && link.text) genres.push(link.text, tag);
        if (state && states.indexOf(state) < 0 && link.text) states.push(link.text, state);
    });
    q(response.body, '.nav-tabs a[href]', response.url).forEach(function(link) {
        var order = match(path(link.href), /^\/category\/order\/(addtime|hits)$/);
        if (order && sorting.indexOf(order) < 0 && link.text) sorting.push(link.text, order);
    });
    if (genres.length < 4 || states.length < 4 || sorting.length < 4) fail('没有取得原站筛选项');
    return [group('genre','题材',genres), group('status','进度',states), group('sort','排序',sorting)];
}

function mh242Book(value) {
    var url = '/comic/' + mh242Id(value);
    var response = get(url);
    if (!own(response.url) || path(response.url) !== url) fail('详情作品身份不匹配');
    return response;
}

function mh242Detail(value) {
    var id = mh242Id(value);
    var response = mh242Book(id);
    var title = text(response.body, 'h1.title');
    var cover = attr(response.body, 'meta[property="og:image"]', 'content');
    if (!title || !cover) fail('详情缺少作品或封面');
    var row = summary(id, title, abs(cover, response.url), attr(response.body, 'meta[property="og:novel:author"]', 'content'));
    row.description = attr(response.body, 'meta[property="og:description"]', 'content');
    return row;
}

function mh242Chapters(value) {
    var id = mh242Id(value);
    var response = mh242Book(id);
    var route = new RegExp('^/chapter/' + id + '_(\\d+)\\.html$');
    var rows = [];
    q(response.body, '.stui-content__playlist a[href]', response.url).forEach(function(link) {
        var cid = match(path(link.href), route);
        if (cid && link.text && own(link.href)) rows.push(chapter(cid, link.text, link.href));
    });
    return ordered(rows, false);
}

function mh242Read(url) {
    if (!own(url) || !/^\/chapter\/\d+_\d+\.html$/.test(path(url))) fail('章节地址无效');
    var response = get(url);
    if (!own(response.url) || path(response.url) !== path(url)) fail('正文身份不匹配');
    var images = q(response.body, '.main .img img', response.url).map(function(node) {
        var value = image(node);
        return value && abs(value, response.url);
    });
    return pageImages(response.url, images, text(response.body, 'h1') || text(response.body, 'title'));
}

function mh242Search(keyword, page) {
    var word = String(keyword || '').trim();
    if (!word) return {items: [], hasMore: false};
    page = mh242Page(page);
    var key = 'mh242:search:' + enc(word) + ':' + page;
    var url = page === 1 ? '/search?key=' + enc(word) : xx.cacheGet(key);
    if (!url) return {items: [], hasMore: false};
    var response = get(url);
    if (!own(response.url) || !/^\/search(?:\/|$)/.test(path(response.url))) fail('搜索地址发生跳转');
    var rows = mh242Rows(response);
    var following = next(response, '.stui-page a[href]');
    var number = following && match(file(following), /(?:\/page\/|[?&]page=)(\d+)(?:\/|&|$)/);
    var more = rows.length > 0 && Number(number) === page + 1;
    if (more) xx.cacheSet('mh242:search:' + enc(word) + ':' + (page + 1), following);
    return {items: rows, hasMore: more};
}

